<?php
 namespace Pterodactyl\Jobs\Dezerx; use Throwable; use Pterodactyl\Jobs\Job; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Cache; use Illuminate\Queue\SerializesModels; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Queue\Middleware\WithoutOverlapping; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Services\Dezerx\Minecraft\VersionCatalog; use Pterodactyl\Services\Dezerx\Minecraft\InstallSteps; use Pterodactyl\Services\Dezerx\Minecraft\InstalledVersion; use Pterodactyl\Services\Dezerx\Minecraft\LaunchConfigurator; class ApplyServerVersion extends Job implements ShouldQueue { use Dispatchable; use InteractsWithQueue; use SerializesModels; public int $timeout = 1800; public int $tries = 1; public int $maxExceptions = 1; private const STATUS_TTL = 1800; public const STALE_AFTER = 300; private const STOP_GRACE_SECONDS = 45; private const KILL_AFTER_SECONDS = 25; private const DELETE_CHUNK = 100; private const EULA_FILE = "#By changing the setting below to TRUE you are indicating your agreement to our EULA (https://aka.ms/MinecraftEULA).\neula=true\n"; public function __construct( public readonly Server $server, public readonly string $platform, public readonly string $version, public readonly ?string $build, public readonly string $jar, public readonly bool $wipe = false, public readonly bool $eula = false, ) { $this->onQueue('standard'); } public function middleware(): array { return [ (new WithoutOverlapping('version:' . $this->server->uuid)) ->releaseAfter(30) ->expireAfter($this->timeout + 60), ]; } public static function statusKey(string $server): string { return 'version-apply:' . $server; } public static function status(string $server): array { return Cache::get(self::statusKey($server)) ?? ['state' => 'idle', 'message' => '', 'at' => 0]; } public static function inFlight(string $server): bool { $status = self::status($server); if (!in_array($status['state'] ?? 'idle', ['queued', 'stopping', 'applying'], true)) { return false; } return (time() - (int) ($status['at'] ?? 0)) < self::STALE_AFTER; } public static function mark(string $server, string $state, string $message): void { Cache::put( self::statusKey($server), ['state' => $state, 'message' => $message, 'at' => time()], self::STATUS_TTL, ); } public function handle(): void { $client = new ServerFiles($this->server); self::mark($this->key(), 'stopping', 'Stopping the server.'); if (! $this->stop($client)) { self::mark( $this->key(), 'failed', 'The server would not stop, so nothing was changed.', ); return; } if ($this->wipe && ! $this->wipeFiles($client)) { self::mark($this->key(), 'failed', 'The server files could not be cleared.'); return; } try { $outcome = $this->install($client); if ($outcome === null) { return; } if ($this->eula) { $client->writeFile('/eula.txt', self::EULA_FILE); } self::mark($this->key(), 'done', $outcome); } catch (Throwable $e) { report($e); self::mark($this->key(), 'failed', 'Applying that version failed.'); } } public function failed(?Throwable $e): void { self::mark( $this->key(), 'failed', 'Applying that version took too long and was stopped.', ); } private function stop(ServerFiles $client): bool { $state = $client->powerState(); if ($state === 'offline') { return true; } $client->setPower('stop'); $waited = 0; $killed = false; while ($waited < self::STOP_GRACE_SECONDS) { sleep(3); $waited += 3; if ($client->powerState() === 'offline') { return true; } if (! $killed && $waited >= self::KILL_AFTER_SECONDS) { Log::info('Version change killing a server that would not stop', [ 'server' => $this->key(), ]); $client->setPower('kill'); $killed = true; } } return $client->powerState() === 'offline'; } private function wipeFiles(ServerFiles $client): bool { self::mark($this->key(), 'applying', 'Deleting the old server files.'); $entries = $client->listFiles('/'); if ($entries === null) { return false; } $names = array_values(array_filter(array_map( fn (array $entry) => (string) ($entry['name'] ?? ''), $entries, ))); if ($names === []) { return true; } foreach (array_chunk($names, self::DELETE_CHUNK) as $chunk) { if (! $client->deletePaths('/', $chunk)) { return false; } } return true; } private function install(ServerFiles $client): ?string { $chosen = VersionCatalog::chosen($this->platform, $this->version, $this->build); $groups = $chosen['installation']; if ($groups === []) { self::mark($this->key(), 'failed', 'That build has no published files.'); return null; } $ran = app(InstallSteps::class)->run( $client, $groups, $this->jar, fn (string $message) => self::mark($this->key(), 'applying', "Installing {$this->version} - {$message}"), ); if (! $ran) { self::mark($this->key(), 'failed', 'That version could not be installed.'); return null; } return $this->configure($client, $chosen); } private function configure(ServerFiles $client, array $chosen): string { self::mark($this->key(), 'applying', 'Setting the startup command.'); $configurator = app(LaunchConfigurator::class); $result = $configurator->apply( $this->server, $client, (int) $chosen['java'], $this->jar, ); InstalledVersion::write($client, [ 'platform' => $this->platform, 'label' => VersionCatalog::platforms()[$this->platform]['label'] ?? $this->platform, 'version' => $this->version, 'build' => $chosen['id'] ?? $this->build, 'buildLabel' => $chosen['label'] ?? null, 'java' => (int) $chosen['java'], ]); $message = "The server is on {$this->version}."; if ($result['target'] !== null) { $message .= " It starts from {$result['target']}."; } if ($result['image'] !== null) { $message .= ' The image was moved to ' . $this->imageLabel($result['image']) . '.'; } return $message . ' It is stopped - start it when you are ready.'; } private function imageLabel(string $image): string { foreach ((array) $this->server->egg->docker_images as $label => $candidate) { if ($candidate === $image) { return (string) $label; } } return $image; } private function key(): string { return $this->server->uuid; } } 